def format_bytes(n):
    """Format a byte count as a human-readable string.

    Examples:
        format_bytes(1500) -> '1.5 KB'
        format_bytes(1500000) -> '1.5 MB'
    """
    if n < 1024:
        return f"{n} B"
    elif n < 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    else:
        return f"{n / (1024 * 1024):.1f} MB"
